x AS (
  SELECT
    w.sub AS sub, r.area AS area, w.y AS y, w.wk AS wk, u.n AS un, (w.wk - u.wf + 1) AS uw, (u.wt - u.wf + 1) AS uweeks,
    u.unit AS unit, u.strand AS strand, r.ln AS ln, r.role AS role, w.f AS tt,
    's3-' || w.sub || '-y' || w.y || '-w' || printf('%02d', w.wk) || '-l' || r.ln AS k
  FROM w
  JOIN u ON u.sub = w.sub AND u.y = w.y AND w.wk BETWEEN u.wf AND u.wt
  JOIN r ON r.sub = w.sub
)
INSERT OR IGNORE INTO lessons (id, family_id, seed_key, title, stage, learning_area, unit_id, status, data, created_at, updated_at)
SELECT
  'seed-' || k, NULL, k,
  'Year ' || y || ', Week ' || wk || ', Lesson ' || ln || ': ' || tt || ' (' || role || ')',
  'S3', area, NULL, 'approved',
  json_object(
    'year_level', 'Year ' || y,
    'subject', strand,
    'unit_title', unit,
    'unit_number', un,
    'week', wk,
    'week_in_unit', uw,
    'lesson_number', ln,
    'lesson_role', role,
    'learning_intention', role || ' lesson in the unit ' || unit || '. Focus: ' || tt || '. Children learn through explicit teaching, guided practice and a short independent task.'
      || CASE WHEN uw = uweeks THEN ' This is the showcase and consolidation week for the unit.' ELSE '' END,
    'outcome_codes', json('[]'),
    'coming_soon', json('true'),
    'source_note', 'Coming soon. This is a planned lesson card. Outcome codes are not assigned yet: map this lesson to the NESA ' || area || ' K-6 Stage 3 syllabus before it is built.'
  ),
  '2026-10-11T09:10:00Z', '2026-10-11T09:10:00Z'
FROM x;
